mapper.select:
SELECT b.id AS budget_id, b.workation_id, b.budget_type, b.expense_category_id, b.target_amount, ec.name AS category_name, ec.description, ec.is_deletable, ec.sort_order, ucl.custom_name, COALESCE(e.spent_amount, 0) AS spent_amount, COALESCE(e.expense_count, 0) AS expense_count FROM budgets b JOIN expense_categories ec ON ec.id = b.expense_category_id LEFT JOIN user_category_labels ucl ON ucl.expense_category_id = ec.id AND ucl.user_id = #{userId} LEFT JOIN ( SELECT workation_id, budget_type, expense_category_id, SUM(amount) AS spent_amount, COUNT(*) AS expense_count FROM workation_expenses WHERE workation_id = #{workationId} GROUP BY workation_id, budget_type, expense_category_id ) e ON e.workation_id = b.workation_id AND e.budget_type = b.budget_type AND e.expense_category_id = b.expense_category_id WHERE b.workation_id = #{workationId}
AND b.budget_type = #{budgetType}
ORDER BY b.budget_type, ec.sort_order

SELECT COUNT(*)
  FROM budgets
 WHERE workation_id = #{workationId}
   AND budget_type  = #{budgetType}

SELECT COUNT(*)
  FROM budgets
 WHERE workation_id        = #{workationId}
   AND budget_type         = #{budgetType}
   AND expense_category_id = #{expenseCategoryId}

